  "chat.toolCall.workflow.run.untracked.body":
    "这个实例不在保留实时状态的最近若干实例之内，但它的运行记录仍然完整。",
  // Transcript 的未启动态：actor 会话在首个 ask 派发时才创建，提前订阅只会失败。
  // 措辞不能说「没有会话记录」——它只是还没开始，而且面板会自己接上。
